import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.WFmvnizL.js";const m=JSON.parse('{"title":"Loading and environment variables","description":"Locate Nezha Dashboard and Agent configuration, use their different environment-variable naming rules, understand persistence, and verify delayed remote configuration changes.","frontmatter":{"description":"Locate Nezha Dashboard and Agent configuration, use their different environment-variable naming rules, understand persistence, and verify delayed remote configuration changes.","outline":"deep"},"headers":[],"relativePath":"en_US/configuration/environment.md","filePath":"en_US/configuration/environment.md","lastUpdated":1792850916000}'),r={name:"en_US/configuration/environment.md"};function i(d,e,s,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="loading-and-environment-variables" tabindex="-1">Loading and environment variables <a class="header-anchor" href="#loading-and-environment-variables" aria-label="Permalink to &quot;Loading and environment variables&quot;">​</a></h1><h2 id="locate-the-active-files" tabindex="-1">Locate the active files <a class="header-anchor" href="#locate-the-active-files" aria-label="Permalink to &quot;Locate the active files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Process</th><th>Default path</th><th>Explicit selection</th></tr></thead><tbody><tr><td>Dashboard</td><td><code>data/config.yaml</code> relative to the working directory</td><td><code>./dashboard -c /path/config.yaml</code></td></tr><tr><td>Dashboard database</td><td><code>data/sqlite.db</code> relative to the working directory</td><td><code>./dashboard -db /path/sqlite.db</code></td></tr><tr><td>Agent</td><td><code>config.yml</code> beside the executable</td><td><code>./nezha-agent -c /path/config.yml</code></td></tr></tbody></table><p>A filename alone does not identify the active configuration. Check systemd <code>ExecStart</code> and <code>WorkingDirectory</code>, or Docker command arguments and mounts. Container paths may differ from host paths.</p><h2 id="dashboard-naming-rules" tabindex="-1">Dashboard naming rules <a class="header-anchor" href="#dashboard-naming-rules" aria-label="Permalink to &quot;Dashboard naming rules&quot;">​</a></h2><p>Dashboard reads variables prefixed with <code>NZ_</code>, removes the prefix, and lowercases the rest. <strong>Underscores introduce nesting.</strong> An individual field normally uses its Go field name without underscores.</p><table tabindex="0"><thead><tr><th>YAML field</th><th>Environment variable</th></tr></thead><tbody><tr><td><code>listen_host</code></td><td><code>NZ_LISTENHOST</code></td></tr><tr><td><code>listen_port</code></td><td><code>NZ_LISTENPORT</code></td></tr><tr><td><code>site_name</code></td><td><code>NZ_SITENAME</code></td></tr><tr><td><code>debug</code></td><td><code>NZ_DEBUG</code></td></tr><tr><td><code>jwt_secret_key</code></td><td><code>NZ_JWTSECRETKEY</code></td></tr><tr><td><code>https.listen_port</code></td><td><code>NZ_HTTPS_LISTENPORT</code></td></tr><tr><td><code>tsdb.data_path</code></td><td><code>NZ_TSDB_DATAPATH</code></td></tr><tr><td><code>tsdb.retention_days</code></td><td><code>NZ_TSDB_RETENTIONDAYS</code></td></tr><tr><td><code>memory.go_mem_limit_mb</code></td><td><code>NZ_MEMORY_GOMEMLIMITMB</code></td></tr></tbody></table><p>For example, <code>NZ_LISTEN_PORT</code> becomes <code>listen.port</code>, not <code>listen_port</code>. Similarly, <code>NZ_TSDB_DATA_PATH</code> is not the correct name for <code>tsdb.data_path</code>. Prefer YAML for complex lists and OAuth2 maps rather than guessing environment syntax.</p><h3 id="loading-and-persistence" tabindex="-1">Loading and persistence <a class="header-anchor" href="#loading-and-persistence" aria-label="Permalink to &quot;Loading and persistence&quot;">​</a></h3><p>Dashboard loads the environment first and then merges YAML. File values can override duplicate settings; avoid overlapping nested keys or alternative spellings. <strong>The environment is not a universal override layer above YAML.</strong></p><p><code>NZ_JWTSECRETKEY</code> is an explicit exception: a nonempty value ultimately wins over the file, is not written back as the JWT secret, and disables automatic key rotation. Other settings may be persisted to YAML when saving admin settings. Environment variables are not a general no-disk-storage mechanism.</p><p>File edits load after a Dashboard restart. Admin settings update runtime state through the API and save the file. File-only settings such as listeners, storage, and JWT options are outside that settings interface.</p><h2 id="agent-naming-rules" tabindex="-1">Agent naming rules <a class="header-anchor" href="#agent-naming-rules" aria-label="Permalink to &quot;Agent naming rules&quot;">​</a></h2><p>Agent also uses <code>NZ_</code>, but <strong>preserves underscores inside field names</strong>. It reads YAML before environment variables. Environment values override simple scalar file settings.</p><table tabindex="0"><thead><tr><th>YAML field</th><th>Environment variable</th></tr></thead><tbody><tr><td><code>server</code></td><td><code>NZ_SERVER</code></td></tr><tr><td><code>client_secret</code></td><td><code>NZ_CLIENT_SECRET</code></td></tr><tr><td><code>uuid</code></td><td><code>NZ_UUID</code></td></tr><tr><td><code>tls</code></td><td><code>NZ_TLS</code></td></tr><tr><td><code>report_delay</code></td><td><code>NZ_REPORT_DELAY</code></td></tr><tr><td><code>disable_command_execute</code></td><td><code>NZ_DISABLE_COMMAND_EXECUTE</code></td></tr></tbody></table><p>Use native YAML arrays and maps. Do not assume comma-separated strings become arrays. Processes inherit their environment at startup: recreate containers after environment changes, or reload service definitions and restart services. Changing an interactive shell does not update an existing service.</p><p>Agent saves configuration when generating a UUID, creating its file, or applying remote configuration. Saved files contain effective configuration and are tightened to <code>0600</code>. <strong>Providing a connection secret through the environment does not guarantee it will never appear in the Agent configuration file.</strong> Protect files and backups.</p><h2 id="remote-configuration-is-delayed" tabindex="-1">Remote configuration is delayed <a class="header-anchor" href="#remote-configuration-is-delayed" aria-label="Permalink to &quot;Remote configuration is delayed&quot;">​</a></h2><p>After the UI or <code>POST /api/v1/server/config</code> sends configuration, Agent validates it and schedules application roughly 10 seconds later. A later ordinary configuration may replace an ordinary update that has not yet applied. The response acknowledges scheduling; a later disk-write failure can still prevent application.</p><p>Application persists the file before publishing runtime configuration and reloading workers. Startup-read options, including <code>debug</code>, automatic-update enablement, and its interval, require a full Agent restart for reliable application. Environment variables can still override remotely saved values on the next startup.</p><ul><li><code>disable_command_execute: true</code> also blocks remote configuration read/apply. Recover locally on the host.</li><li>Ordinary configuration pushes cannot rotate <code>client_secret</code>. Server transfers use their dedicated workflow, not the generic configuration API.</li><li>Preserve host access before changing connection addresses or TLS. An unreachable Agent cannot be repaired through its former Dashboard connection.</li></ul><h2 id="troubleshoot-ineffective-edits" tabindex="-1">Troubleshoot ineffective edits <a class="header-anchor" href="#troubleshoot-ineffective-edits" aria-label="Permalink to &quot;Troubleshoot ineffective edits&quot;">​</a></h2><ol><li>Confirm the active <code>-c</code> file and container mount.</li><li>Check for duplicate <code>NZ_</code> variables without printing credentials into logs or issue reports.</li><li>Restart after local file edits; recreate containers after environment changes.</li><li>Allow the remote application window, inspect Agent logs, and confirm new reports instead of relying on the submission response.</li><li>For settings-save failures, check write permissions on the configuration directory, not only the file.</li><li>Cross-check logs, API readback, and effective behavior. See <a href="/en_US/configuration/examples.html">configuration recipes and verification</a>.</li></ol><h2 id="implementation-references" tabindex="-1">Implementation references <a class="header-anchor" href="#implementation-references" aria-label="Permalink to &quot;Implementation references&quot;">​</a></h2><ul><li><a href="https://github.com/nezhahq/nezha/blob/master/model/config.go" target="_blank" rel="noreferrer">Dashboard loading and persistence</a></li><li><a href="https://github.com/nezhahq/nezha/blob/master/cmd/dashboard/controller/setting.go" target="_blank" rel="noreferrer">Dashboard settings API</a></li><li><a href="https://github.com/nezhahq/agent/blob/main/model/config.go" target="_blank" rel="noreferrer">Agent loading and validation</a></li><li><a href="https://github.com/nezhahq/agent/blob/main/cmd/agent/main.go" target="_blank" rel="noreferrer">Agent configuration application</a></li></ul>',25)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
